nt, factory, line, snapshot_date UNION ALL SELECT 'FilterRef' as granularity, '' as period_name, 99 as sort_order, '' as vx_type, '' as region, '' as plant, '' as factory, '' as line, (SELECT anchor_dt FROM anchor) as filter_date, (SELECT anchor_dt FROM anchor) as snapshot_date_real, 0 as total_qty, 0 as todo_qty, 0 as doing_qty, 0 as doing_done_qty, 0 as done_qty, 0 as acc_qty, 0 as acc_total_qty FROM (SELECT DISTINCT snapshot_date FROM gold.rmv_l5_task_completion_phys);
